from __future__ import annotations


TEMPLATE_PATH = 'frontend/app/register/page.tsx'
TEMPLATE_CONTENT = '"use client";\n\nimport { FormEvent, useState } from "react";\nimport { register } from "../../lib/api";\nimport { saveAccessToken } from "../../lib/auth";\nimport { SAFE_ERROR_MESSAGES } from "../../lib/errors";\n\nexport default function RegisterPage() {\n  const [username, setUsername] = useState("");\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [errorMessage, setErrorMessage] = useState("");\n\n  async function handleSubmit(event: FormEvent<HTMLFormElement>) {\n    event.preventDefault();\n    setErrorMessage("");\n\n    try {\n      const response = await register(username, email, password);\n      saveAccessToken(response.access_token);\n      window.location.href = "/dashboard";\n    } catch {\n      setErrorMessage(SAFE_ERROR_MESSAGES.registerFailed);\n    }\n  }\n\n  return (\n    <main className="mx-auto max-w-md px-6 py-12">\n      <h1 className="mb-6 text-2xl font-semibold">Create account</h1>\n\n      <form onSubmit={handleSubmit} className="space-y-4">\n        <input\n          className="w-full rounded border px-3 py-2"\n          placeholder="Username"\n          value={username}\n          onChange={(event) => setUsername(event.target.value)}\n        />\n\n        <input\n          className="w-full rounded border px-3 py-2"\n          placeholder="Email"\n          type="email"\n          value={email}\n          onChange={(event) => setEmail(event.target.value)}\n        />\n\n        <input\n          className="w-full rounded border px-3 py-2"\n          placeholder="Password"\n          type="password"\n          value={password}\n          onChange={(event) => setPassword(event.target.value)}\n        />\n\n        {errorMessage ? (\n          <p className="text-sm text-red-600">{errorMessage}</p>\n        ) : null}\n\n        <button className="w-full rounded bg-black px-4 py-2 text-white" type="submit">\n          Register\n        </button>\n      </form>\n    </main>\n  );\n}\n'
